// In-memory test doubles with the same interfaces as CampaignChain, SwarmService and Arkiv (reads + business wallet).
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { REPO_ROOT } from "../src/config.js";
import { parseGlb, sha256 } from "../src/glb.js";

export const RARITY = ["COMMON", "RARE", "EPIC", "LEGENDARY"];
// Test fixture (generated by scripts/generate-creature-glb.mjs), independent of the user's assets folder.
export const FIXTURES_DIR = join(REPO_ROOT, "worker", "test", "fixtures");
export const BASE_GLB = readFileSync(join(FIXTURES_DIR, "ember-fox.glb"));
export const BASE_REF = "a".repeat(64);

export class FakeChain {
  constructor({ campaignId = 1n, rarities = [0, 0, 0, 0, 0, 0, 1, 1, 2, 3], status = "ALLOCATED" } = {}) {
    this.chainId = 31337;
    this.address = "0x5FbDB2315678afecb367f032d93F642f64180aa3";
    this.campaignId = campaignId;
    this.rarities = rarities;
    this.status = status;
    this.rewards = RARITY.map((r) => ({ code: `${r}-CODE`, description: `${r} reward` }));
  }
  async getCampaign() {
    return {
      business: BUSINESS,
      status: ["NONE", "RANDOMNESS_REQUESTED", "ALLOCATED", "CANCELLED"].indexOf(this.status),
      statusName: this.status,
      totalCreatures: this.rarities.length,
      expiresAt: 0n,
      vrfRequestId: 7n,
      swarmReference: BASE_REF,
      businessName: "Chai Point",
    };
  }
  async getRewards() {
    return this.rewards;
  }
  async getAllCreatures(campaignId, total) {
    return this.rarities.slice(0, total).map((r, i) => ({
      creatureId: (BigInt(campaignId) << 32n) | BigInt(i),
      campaignId: BigInt(campaignId),
      index: i,
      business: BUSINESS,
      businessName: "Chai Point",
      rarity: r,
      rarityName: RARITY[r],
      discountCode: this.rewards[r].code,
      discountDescription: this.rewards[r].description,
      latitudeE6: 19076090,
      longitudeE6: 72877426,
      expiresAt: 0n,
      swarmReference: BASE_REF,
      createdAt: 1750000000n,
    }));
  }
  async getCampaignTxHashes() {
    return { creationTxHash: "0x" + "1".repeat(64), allocationTxHash: "0x" + "2".repeat(64) };
  }
}

export class FakeSwarm {
  constructor() {
    this.store = new Map([[BASE_REF, BASE_GLB]]);
    this.uploads = 0;
    this.failFor = new Set(); // filenames that fail
  }
  async download(ref) {
    if (!this.store.has(ref)) throw new Error("not found");
    return { data: this.store.get(ref), name: "x.glb", contentType: "model/gltf-binary" };
  }
  async uploadGlb(buf, filename) {
    parseGlb(buf);
    if (this.failFor.has(filename)) throw new Error(`swarm down for ${filename}`);
    this.uploads++;
    const ref = sha256(buf); // content addressed, like Swarm
    this.store.set(ref, buf);
    return { reference: ref, sha256: ref, size: buf.length, filename };
  }
}

export const BUSINESS = "0x70997970C51812dc3A010C7d01b50e0d17dc79C8";
export const STRANGER = "0x3C44CdDdB6a900fa2b585dd299e03d12FA4293BC";

const plain = (x) => (x && typeof x === "object" && "value" in x ? x.value : x);

/**
 * In-memory Arkiv: the read API of ArkivCreatureStore plus wallet clients whose executeBatch behaves
 * like the SDK's (one atomic tx per call; the SIGNER becomes $creator and $owner).
 */
export class MemoryArkiv {
  constructor() {
    this.schemaName = "ethglobal-mumbai-2026.creature.v2";
    this.entities = new Map(); // key -> { creator, owner, values (plain), flags, expiration }
    this.batchCalls = 0;
    this.nextKey = 1;
    this.failCreatureIds = new Set(); // reject any batch containing these (nothing written)
    this.landThenThrow = 0; // upcoming batches that are written but whose receipt is "lost"
    this.hiddenFromQuery = new Set(); // simulate query index lag
  }

  /** Same contract as ArkivCreatureStore.findCampaignEntities ($creator + campaign identity). */
  async findCampaignEntities({ creator, chainId, contract, campaignId }) {
    const found = new Map();
    for (const [key, e] of this.entities) {
      const v = e.values;
      if (this.hiddenFromQuery.has(key)) continue;
      if (e.creator.toLowerCase() !== creator.toLowerCase()) continue;
      if (BigInt(v.campaignId) !== BigInt(campaignId) || BigInt(v.chainId) !== BigInt(chainId) || v.contract.toLowerCase() !== contract.toLowerCase()) continue;
      found.set(v.creatureId, [...(found.get(v.creatureId) || []), this._summary(key)]);
    }
    return found;
  }

  async getCreatureEntity(key) {
    return this.entities.has(key) ? this._summary(key) : null;
  }

  _summary(key) {
    const e = this.entities.get(key);
    return { key, creator: e.creator, owner: e.owner, creatureId: e.values.creatureId, rarity: e.values.rarity, discountCode: e.values.discountCode, swarmReference: e.values.swarmReference };
  }

  /** A wallet client for `address` (what MetaMask + the SDK wallet client are to the browser). */
  walletFor(address) {
    return {
      account: { address },
      executeBatch: async ({ creates }) => {
        this.batchCalls++;
        const values = creates.map((c) => Object.fromEntries(Object.entries(c.values).map(([k, v]) => [k, plain(v)])));
        if (values.some((v) => this.failCreatureIds.has(v.creatureId))) throw new Error("arkiv rpc error");
        const keys = values.map((v, i) => {
          const key = "0x" + (this.nextKey++).toString(16).padStart(64, "0");
          this.entities.set(key, { creator: address, owner: address, values: v, flags: creates[i].flags, expiration: creates[i].expiration });
          return key;
        });
        if (this.landThenThrow > 0) {
          this.landThenThrow--;
          throw new Error("timeout waiting for receipt");
        }
        return { txHash: "0x" + "f".repeat(64), createdEntities: keys };
      },
    };
  }
}
